// Home Assistant's automations and scripts, as ha-config keeps them, for the Automations view.
// Written by tools/automations.py (re-run it after the automations change); do not edit by hand.
'use strict';
const HA_AUTOS = {"1784768589409":{"alias":"HVAC - Sync Windmill AC with Office Thermostat","description":"Synchronizes the Windmill AC unit setpoint and HVAC mode exclusively with the Office thermostat using a non-linear temperature offset.","triggers":[{"entity_id":"climate.office_office","attribute":"target_temp_high","trigger":"state"},{"entity_id":"climate.office_office","attribute":"temperature","trigger":"state"},{"entity_id":"climate.office_office","not_to":["unavailable","unknown"],"trigger":"state"}],"conditions":[{"condition":"template","value_template":"{{ states('climate.office_office') not in ['unavailable', 'unknown'] }}"}],"actions":[{"if":[{"condition":"state","entity_id":"climate.office_office","state":"off"}],"then":[{"action":"climate.set_hvac_mode","target":{"entity_id":"climate.windmill_ac"},"data":{"hvac_mode":"off"}}],"else":[{"action":"climate.set_temperature","target":{"entity_id":"climate.windmill_ac"},"data":{"hvac_mode":"{{ 'auto' if is_state('climate.windmill_ac', 'auto') else 'cool' }}","temperature":"{% set office_temp = state_attr('climate.office_office', 'target_temp_high') \n                     if state_attr('climate.office_office', 'target_temp_high') is not none \n                     else state_attr('climate.office_office', 'temperature') | float(78) %}\n{% if office_temp >= 80 %}\n  {{ office_temp - 2 }}\n{% else %}\n  {{ office_temp - 3 }}\n{% endif %}"}}]}],"mode":"single"},"1785000000001":{"alias":"Goodnight","description":"Shuts the house down for the night. Run on demand - from the Goodnight pill on the Favorites view, via automation.trigger, or by firing the `goodnight` event. Nothing fires it on a schedule.\nAlso enrols the Kitchen, Garage and Living Room Blink cameras for motion detection, and asserts that the sync module is armed. The Yard camera is left alone - it watches around the clock. Mom's Awake un-enrols those three.\nExcluded on purpose: Elena's lamp goes to 1% rather than off - and note that light.master_bedroom is deliberately absent from the turn-off list because that group contains her lamp. light.outdoor_front and light.garage_door are never touched either - they are outdoor lights, left on overnight and switched off before dawn by \"Evening Lights - Off Before Sunrise\". The deck is the one outdoor light this routine does switch off. The heater backlights are left alone too - they belong to the heaters, not to the rooms, and are controlled from the Climate view.","triggers":[{"trigger":"event","event_type":"goodnight"}],"conditions":[],"actions":[{"action":"input_boolean.turn_off","continue_on_error":true,"target":{"entity_id":"input_boolean.thermostat_hold"}},{"action":"script.turn_on","continue_on_error":true,"target":{"entity_id":"script.thermostat_apply"},"data":{"variables":{"phase":"night"}}},{"action":"light.turn_off","target":{"entity_id":["light.side_lamps","light.floor_lamps","light.morocco","light.spotlight","light.living_room_fireplace_lights_socket","light.cocktail_main","light.tv_lamps","light.tian_hao_rgbdeng_dai_kong_zhi_qi_wifi","light.bar_main_light_1","light.kitchen","light.kitchen_fan","light.sofias_lamp","light.tom_lamp"]}},{"action":"light.turn_off","target":{"entity_id":"light.outdoor_deck"}},{"action":"light.turn_on","target":{"entity_id":"light.elena_lamp"},"data":{"brightness_pct":1}},{"action":"input_boolean.turn_on","target":{"entity_id":"input_boolean.front_doorbell_camera_power"}},{"action":"script.turn_on","target":{"entity_id":"script.blink_set_enrolment"},"data":{"variables":{"state":"on","reason":"Goodnight","entities":["switch.garage_camera_motion_detection","switch.kitchen_camera_motion_detection","switch.living_room_camera_motion_detection"]}}},{"action":"alarm_control_panel.alarm_arm_away","continue_on_error":true,"target":{"entity_id":"alarm_control_panel.blink_system"}},{"action":"media_player.media_stop","continue_on_error":true,"target":{"entity_id":["media_player.kitchen_sonos_kitchen_sonos","media_player.living_room_sonos_living_room_sonos","media_player.office_sonos_office_sonos","media_player.sonos_arc_sub_sonos_arc_sub","media_player.nest_mini"]}},{"action":"media_player.volume_set","continue_on_error":true,"target":{"entity_id":["media_player.kitchen_sonos_kitchen_sonos","media_player.living_room_sonos_living_room_sonos","media_player.office_sonos_office_sonos","media_player.sonos_arc_sub_sonos_arc_sub","media_player.nest_mini"]},"data":{"volume_level":0.15}},{"if":[{"condition":"not","conditions":[{"condition":"state","entity_id":"media_player.65_oled","state":["off","unavailable","unknown"]}]}],"then":[{"action":"media_player.turn_off","target":{"entity_id":"media_player.65_oled"}}]}],"mode":"single"},"1754320000000":{"alias":"Evening Lights — Sunset Ladder","description":"Replaces the lux-modelled pair this used to be (retired 2026-08-13): sensor.estimated_outdoor_lux and sensor.evening_lights_target_brightness tried to infer real-world darkness from sun elevation and cloud cover, and the model kept misfiring - most recently raising the manual-off suppression flag at 07:09 on a clear, unambiguous morning. This is the deliberately dumb replacement: three fixed points relative to sunset, no lux, no cloud model, no ladder sensor for two automations to keep in step.\n100% one hour before sunset, 50% at sunset, 25% one hour after sunset - the Living Room and Lounge lamps. The fireplace socket, the TV strip (flat 100%) and the outdoor front/deck/garage set (1%) come on at the first step and are not re-touched by the later two, same scope as the old automation.\nRespects input_boolean.evening_lights_suppressed exactly like the old pair did: switching a light off during the evening keeps it off rather than being reset at the next step. \"Evening Lights — Manual Off Suppresses\" and \"Evening Lights — Off Before Sunrise\" are unchanged and still own that flag.\nTHE ARRIVED-HOME GAP IS NOW CLOSED (2026-08-16). This used to note that getting home after all three steps had passed left the lights off until the next evening. A fourth trigger fires when the first person gets home and works the level out from the clock, landing on the same 100/50/25 bands, so arriving at half nine gets the 25% scene rather than darkness. It also brings up the fireplace, TV strip and outdoor set, since on a night nobody was home none of those came on either.\nPresence is EITHER person, not just Tom - see the conditions.","triggers":[{"trigger":"sun","event":"sunset","offset":"-01:00:00","id":"step_100"},{"trigger":"sun","event":"sunset","id":"step_50"},{"trigger":"sun","event":"sunset","offset":"01:00:00","id":"step_25"},{"trigger":"state","entity_id":["person.tomallison24","person.elena"],"to":"home","id":"arrived"}],"conditions":[{"condition":"template","value_template":"{{ (trigger.id | default('')) == 'arrived'\n   or is_state('input_boolean.evening_lights_suppressed', 'off') }}"},{"condition":"template","value_template":"{% set home = [states('person.tomallison24'), states('person.elena')]\n              | select('eq', 'home') | list | count %}\n{{ home >= 1\n   and ((trigger.id | default('')) != 'arrived' or home == 1) }}"},{"condition":"template","value_template":"{{ is_state('sun.sun', 'below_horizon')\n   or (as_timestamp(state_attr('sun.sun', 'next_setting'))\n       - as_timestamp(now())) <= 3600 }}"}],"actions":[{"variables":{"tid":"{{ trigger.id if trigger is defined and trigger is not none else '' }}","target_pct":"{% if tid in ['step_100', 'step_50', 'step_25'] %}\n  {{ {'step_100': 100, 'step_50': 50, 'step_25': 25}[tid] }}\n{% elif tid == 'arrived' %}\n  {% set ns = as_timestamp(state_attr('sun.sun', 'next_setting')) %}\n  {% set sunset_ts = ns - (86400 if is_state('sun.sun', 'below_horizon') else 0) %}\n  {% set mins = (as_timestamp(now()) - sunset_ts) / 60 %}\n  {{ 100 if mins < 0 else (50 if mins < 60 else 25) }}\n{% else %}\n  100\n{% endif %}","interior_lights":["light.floor_lamps","light.morocco","light.spotlight","light.side_lamps","light.cocktail_main","light.tv_lamps","light.bar_main_light_1"]}},{"action":"light.turn_on","target":{"entity_id":"{{ interior_lights }}"},"data":{"brightness_pct":"{{ target_pct }}"}},{"delay":{"seconds":2}},{"action":"light.turn_on","target":{"entity_id":"{{ interior_lights }}"},"data":{"brightness_pct":"{{ target_pct }}"}},{"if":[{"condition":"template","value_template":"{{ tid in ['step_100', '', 'arrived'] }}"}],"then":[{"action":"light.turn_on","target":{"entity_id":"light.living_room_fireplace_lights_socket"}},{"action":"light.turn_on","target":{"entity_id":"light.tian_hao_rgbdeng_dai_kong_zhi_qi_wifi"},"data":{"brightness_pct":100}},{"action":"light.turn_on","target":{"entity_id":["light.outdoor_front","light.outdoor_deck","light.garage_door"]},"data":{"brightness_pct":1}}]}],"mode":"single"},"1754320000002":{"alias":"Evening Lights — Off Before Sunrise","description":"Switches off the garage, three hours before sunrise. Sun-relative rather than a clock time, so it tracks the seasons on its own - no adjusting it twice a year.\nSEPARATE from the turn-on automation on purpose. That one is driven by sunset offsets and presence; this one is driven by sunrise and cares about neither. Folding them together would mean branching on trigger id inside the actions and guarding every condition so the wrong half did not run. Two automations with one job each can be read, traced and disabled independently.\nTHE DECK IS NOT HERE - deliberately, since 2026-08-13. Goodnight already switches it off at bedtime, and Off Before Sunrise switching it off too made two automations claim the same light for no reason. Garage stays lit all night on purpose - it lights the approach to the house - so only this automation ever turns it off. The interior lights are not touched either: Goodnight handles those too, at the point you actually go to bed, which is a better moment to switch off a lamp you might still be sitting under than a fixed hour before dawn.\nOUTDOOR FRONT USED TO BE HERE TOO, until 2026-09-14, when it moved to its own fixed-time automation (\"Evening Lights - Outdoor Front Off at 22:30\") so it goes off at 22:30 every night instead of tracking sunrise. The garage keeps the old sunrise-relative behaviour unchanged.","triggers":[{"trigger":"sun","event":"sunrise","offset":"-03:00:00"}],"conditions":[],"actions":[{"action":"light.turn_off","target":{"entity_id":"light.garage_door"}},{"action":"input_boolean.turn_off","target":{"entity_id":"input_boolean.evening_lights_suppressed"}}],"mode":"single"},"1754320000004":{"alias":"Evening Lights — Outdoor Front Off at 22:30","description":"Switches off light.outdoor_front (the group covering outdoor_front_1 and outdoor_front_2) at a fixed clock time every night, instead of tracking sunrise like the garage still does.\nSplit out from \"Off Before Sunrise\" on 2026-09-14 at the user's request - the front pair used to stay lit all night alongside the garage, but should now go off at a set time regardless of season. A fixed time rather than a sun-relative offset because the request was specifically for a clock time, not a schedule that drifts with sunrise.\nNo conditions: if the light happens to already be off, turning it off again is a no-op. No suppression-flag interaction either - that flag only gates the sunset turn-on ladder for the interior lamps, and never watched light.outdoor_front.","triggers":[{"trigger":"time","at":"22:30:00"}],"conditions":[],"actions":[{"action":"light.turn_off","target":{"entity_id":"light.outdoor_front"}}],"mode":"single"},"1785890100001":{"alias":"Blinds - Open Office Blinds at 08:30","description":"Opens both VELUX office blinds fully each morning. Skipped entirely while guest mode is on, so nothing raises the blinds on someone sleeping in the office.\n\nTargets cover.office_blinds, the group defined in configuration.yaml, rather than the two covers individually - one call, and the group is what the dashboard pill drives too.","triggers":[{"trigger":"time","at":"08:30:00"}],"conditions":[{"condition":"state","entity_id":"input_boolean.guest_mode","state":"off"}],"actions":[{"action":"cover.set_cover_position","target":{"entity_id":"cover.office_blinds"},"data":{"position":100}}],"mode":"single"},"1785890100002":{"alias":"Blinds - Close Office Blinds at Sunset","description":"Closes both VELUX office blinds at sunset. Skipped while guest mode is on, matching the morning automation - a guest who has set the blinds where they want them should not have them moved at either end of the day.\n\nSunset rather than a fixed time so it tracks the season; change the offset on the trigger to close before or after.","triggers":[{"trigger":"sun","event":"sunset"}],"conditions":[{"condition":"state","entity_id":"input_boolean.guest_mode","state":"off"}],"actions":[{"action":"cover.set_cover_position","target":{"entity_id":"cover.office_blinds"},"data":{"position":0}}],"mode":"single"},"1785890100003":{"alias":"Blinds - Catch Up After Guest Mode","description":"Moves the office blinds to wherever the schedule says they should be the moment guest mode is switched off.\n\nWithout this, clearing guest mode changes nothing until the next trigger: guests leaving at 10am would leave the blinds shut until sunset, because the 08:30 run was skipped and is not replayed. This is the replay.\n\nThe window is 08:30 -> sunset, which is exactly the span between the two scheduled automations, so this can never disagree with them. Inside it, open; outside it, closed.","triggers":[{"trigger":"state","entity_id":"input_boolean.guest_mode","from":"on","to":"off"}],"conditions":[],"actions":[{"choose":[{"conditions":[{"condition":"time","after":"08:30:00"},{"condition":"sun","before":"sunset"}],"sequence":[{"action":"cover.set_cover_position","target":{"entity_id":"cover.office_blinds"},"data":{"position":100}}]}],"default":[{"action":"cover.set_cover_position","target":{"entity_id":"cover.office_blinds"},"data":{"position":0}}]}],"mode":"single"},"1785890100004":{"alias":"Blinds - Push Slider Targets To Blinds","description":"Drives each blind from its own input_number.*_target helper, which is what the dashboard sliders and chips actually write to. Handles all three - the group and both individual blinds - by deriving the cover from whichever helper fired, so adding a fourth blind means adding a helper and a trigger line, not another automation.\n\nPairing this with \"Sync Slider Targets From Blinds\" is what makes a slider move the moment a chip is tapped rather than several seconds later: the helper changes instantly, the blind follows, and the display never has to wait on a cloud poll.","variables":{"target_cover":"{{ trigger.entity_id | replace('input_number.', 'cover.') | replace('_target', '') }}"},"triggers":[{"trigger":"state","entity_id":["input_number.office_blinds_target","input_number.office_left_blind_target","input_number.office_right_blind_target"]}],"conditions":[{"condition":"template","value_template":"{{ ((state_attr(target_cover, 'current_position') | int(0))\n    - (states(trigger.entity_id) | int(0))) | abs > 2 }}"}],"actions":[{"action":"cover.set_cover_position","target":{"entity_id":"{{ target_cover }}"},"data":{"position":"{{ states(trigger.entity_id) | int(0) }}"}}],"mode":"parallel"},"1785890100005":{"alias":"Blinds - Sync Slider Targets From Blinds","description":"Keeps every dashboard slider honest when the blinds move for a reason that slider did not cause - the 08:30 and sunset runs, the guest-mode catch-up, the physical VELUX remote, or the group being set and both members following.\n\nWithout this a helper would hold whatever was last tapped and its slider would slowly become a lie.","variables":{"target_helper":"{{ trigger.entity_id | replace('cover.', 'input_number.') ~ '_target' }}"},"triggers":[{"trigger":"state","entity_id":["cover.office_blinds","cover.office_left_blind","cover.office_right_blind"],"attribute":"current_position"}],"conditions":[{"condition":"template","value_template":"{{ states(trigger.entity_id) not in ['opening', 'closing'] }}"},{"condition":"template","value_template":"{{ ((state_attr(trigger.entity_id, 'current_position') | int(0))\n    - (states(target_helper) | int(0))) | abs > 2 }}"}],"actions":[{"action":"input_number.set_value","target":{"entity_id":"{{ target_helper }}"},"data":{"value":"{{ state_attr(trigger.entity_id, 'current_position') | int(0) }}"}}],"mode":"parallel"},"1754320000003":{"alias":"Evening Lights — Manual Off Suppresses","description":"Watches for any evening interior light being switched off while it's dark out, and raises input_boolean.evening_lights_suppressed when it happens. \"Evening Lights — Sunset Ladder\" refuses to run while that flag is up, so switching the lights off actually keeps them off instead of being undone by the next trigger.\nFires for ANY route to off - a dashboard pill, a physical switch, the Goodnight routine, a voice command. It watches the lights themselves rather than trying to know who turned them off, which is what makes it cover cases nobody thought of.\nThe flag clears three hours before sunrise, in \"Evening Lights - Off Before Sunrise\", so tomorrow evening starts clean. Tapping the Evening Lights pill also clears it.","triggers":[{"trigger":"state","entity_id":["light.floor_lamps","light.morocco","light.side_lamps","light.spotlight","light.cocktail_main","light.tv_lamps","light.bar_main_light_1","light.living_room_fireplace_lights_socket"],"to":"off"}],"conditions":[{"condition":"template","value_template":"{{ is_state('sun.sun', 'below_horizon')\n   and (as_timestamp(state_attr('sun.sun', 'next_rising'))\n        - as_timestamp(now())) > 3 * 3600 }}"},{"condition":"template","value_template":"{{ [states('person.tomallison24'), states('person.elena')]\n   | select('eq', 'home') | list | count >= 1 }}"}],"actions":[{"action":"input_boolean.turn_on","target":{"entity_id":"input_boolean.evening_lights_suppressed"}}],"mode":"single"},"1785900000001":{"alias":"Mom's Awake","description":"Sets the living room up for Mom being up and about. Run on demand - via automation.trigger, from a dashboard pill, or by firing the `moms_awake` event. Nothing fires it on a schedule.\nLamps go to 25%, the fireplace socket simply goes on because it has no dimmer, and the Nest doorbell feed is dropped from the dashboards while she is up. It is the mirror image of the feed step in Goodnight, which turns that helper back on.\nThe Kitchen, Garage and Living Room Blink cameras are un-enrolled from motion detection here, which genuinely stops them watching - something the Nest doorbell cannot be made to do from HA. The sync module stays armed and the Yard camera keeps watching the outside of the house throughout.","triggers":[{"trigger":"event","event_type":"moms_awake"}],"conditions":[],"actions":[{"action":"input_boolean.turn_off","target":{"entity_id":"input_boolean.front_doorbell_camera_power"}},{"action":"script.turn_on","target":{"entity_id":"script.blink_set_enrolment"},"data":{"variables":{"state":"off","reason":"Mom's Awake","entities":["switch.garage_camera_motion_detection","switch.kitchen_camera_motion_detection","switch.living_room_camera_motion_detection"]}}},{"action":"light.turn_on","target":{"entity_id":["light.floor_lamps","light.tv_lamps","light.side_lamps"]},"data":{"brightness_pct":25}},{"action":"light.turn_on","target":{"entity_id":"light.tian_hao_rgbdeng_dai_kong_zhi_qi_wifi"},"data":{"brightness_pct":100}},{"action":"light.turn_on","target":{"entity_id":"light.living_room_fireplace_lights_socket"}}],"mode":"single"},"signal_tv_strip_remember_custom_colour":{"alias":"Signal — TV Strip: remember custom colour","description":"Stores the strip's colour in input_text.signal_tv_strip_custom_hs whenever it settles on something that is not one of the six fixed swatches, so the Custom swatch on the lights view can put it back.","triggers":[{"trigger":"state","entity_id":"light.tian_hao_rgbdeng_dai_kong_zhi_qi_wifi","attribute":"hs_color","for":"00:00:03"}],"conditions":[{"condition":"template","value_template":"{% set e = 'light.tian_hao_rgbdeng_dai_kong_zhi_qi_wifi' %} {% set hs = state_attr(e,'hs_color') %} {% set ns = namespace(preset=false) %} {% if hs %}\n  {% for p in [[30,25],[0,100],[120,100],[220,100],[280,100]] %}\n    {% set d = [ (hs[0] - p[0]) | abs, 360 - ((hs[0] - p[0]) | abs) ] | min %}\n    {% if d <= 12 and (hs[1] - p[1]) | abs <= 15 %}{% set ns.preset = true %}{% endif %}\n  {% endfor %}\n{% endif %} {{ is_state(e,'on') and state_attr(e,'color_mode') != 'white'\n   and hs and not ns.preset }}"}],"actions":[{"action":"input_text.set_value","target":{"entity_id":"input_text.signal_tv_strip_custom_hs"},"data":{"value":"{% set hs = state_attr('light.tian_hao_rgbdeng_dai_kong_zhi_qi_wifi','hs_color') %} {{ hs[0] | round(0) | int }},{{ hs[1] | round(0) | int }}"}}],"mode":"restart"},"signal_dyson_remember_speed":{"alias":"Signal — Dyson: remember running speed","description":"Keeps input_number.*_previous_speed holding the speed each Dyson was last actually running at, so the cards can show it while the unit is off and so \"Signal — Dyson: restore speed\" has something to put back.","triggers":[{"trigger":"state","entity_id":["fan.m_d_dyson","fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"attribute":"percentage"},{"trigger":"state","entity_id":["fan.m_d_dyson","fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"to":"on","for":"00:00:15"},{"trigger":"time_pattern","minutes":"/5"}],"actions":[{"repeat":{"for_each":[{"fan":"fan.m_d_dyson","prev":"input_number.m_d_dyson_previous_speed"},{"fan":"fan.sofias_dyson","prev":"input_number.sofia_s_dyson_previous_speed"},{"fan":"fan.olivia_s_bedroom_olivias_dyson","prev":"input_number.olivia_s_dyson_previous_speed"}],"sequence":[{"if":[{"condition":"template","value_template":"{{ is_state(repeat.item.fan, 'on')\n   and state_attr(repeat.item.fan, 'percentage') | int(0) > 0 }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"{{ repeat.item.prev }}"},"data":{"value":"{{ state_attr(repeat.item.fan, 'percentage') | int }}"}}]}]}}],"mode":"queued"},"signal_dyson_restore_speed":{"alias":"Signal — Dyson: default speed on turn-on","description":"Sets every Dyson to speed 2 (20%) a few seconds after a manual turn-on, and again a few seconds after it leaves Auto mode while staying on. Does nothing while the unit is actually in Auto.","triggers":[{"trigger":"state","entity_id":["fan.m_d_dyson","fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"from":"off","to":"on"},{"trigger":"state","entity_id":["fan.m_d_dyson","fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"attribute":"preset_mode","from":"Auto"}],"actions":[{"delay":"00:00:05"},{"condition":"template","value_template":"{% set boost = {'fan.m_d_dyson': 'input_boolean.signal_dyson_md_boost',\n                'fan.sofias_dyson': 'input_boolean.signal_dyson_sofia_boost',\n                'fan.olivia_s_bedroom_olivias_dyson': 'input_boolean.signal_dyson_olivia_boost'} %}\n{{ is_state(trigger.entity_id, 'on')\n   and state_attr(trigger.entity_id, 'preset_mode') != 'Auto'\n   and not is_state(boost.get(trigger.entity_id, ''), 'on') }}"},{"action":"fan.set_percentage","target":{"entity_id":"{{ trigger.entity_id }}"},"data":{"percentage":20}}],"mode":"parallel"},"signal_dyson_remember_night":{"alias":"Signal — Dyson: remember night mode","description":"Holds the night mode each girl's Dyson was last running with in input_boolean.*_previous_night, so it survives the unit losing power and \"Signal — Dyson: restore night mode\" can put it back.","triggers":[{"trigger":"state","entity_id":["switch.sofias_dyson_night_mode","switch.olivia_s_bedroom_olivias_dyson_night_mode"],"for":"00:00:10"},{"trigger":"state","entity_id":["fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"to":"on","for":"00:00:15"},{"trigger":"time_pattern","minutes":"/5"}],"actions":[{"repeat":{"for_each":[{"fan":"fan.sofias_dyson","night":"switch.sofias_dyson_night_mode","prev":"input_boolean.sofia_s_dyson_previous_night"},{"fan":"fan.olivia_s_bedroom_olivias_dyson","night":"switch.olivia_s_bedroom_olivias_dyson_night_mode","prev":"input_boolean.olivia_s_dyson_previous_night"}],"sequence":[{"if":[{"condition":"template","value_template":"{{ is_state(repeat.item.fan, 'on')\n   and states(repeat.item.night) in ['on', 'off']\n   and (is_state(repeat.item.night, 'on')\n        or (now() - states[repeat.item.night].last_changed).total_seconds() > 10) }}"}],"then":[{"action":"input_boolean.turn_{{ states(repeat.item.night) }}","target":{"entity_id":"{{ repeat.item.prev }}"}}]}]}}],"mode":"queued"},"signal_dyson_restore_night":{"alias":"Signal — Dyson: restore night mode on turn-on","description":"When one of the girls' Dysons comes back on without the night mode it was last running with, switches it back on. Does nothing if the unit already restored it itself, which is the usual case.","variables":{"night_map":{"fan.sofias_dyson":"switch.sofias_dyson_night_mode","fan.olivia_s_bedroom_olivias_dyson":"switch.olivia_s_bedroom_olivias_dyson_night_mode"},"prev_map":{"fan.sofias_dyson":"input_boolean.sofia_s_dyson_previous_night","fan.olivia_s_bedroom_olivias_dyson":"input_boolean.olivia_s_dyson_previous_night"},"night":"{{ night_map[trigger.entity_id] }}","prev":"{{ prev_map[trigger.entity_id] }}"},"triggers":[{"trigger":"state","entity_id":["fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"from":"off","to":"on"}],"actions":[{"delay":"00:00:05"},{"condition":"template","value_template":"{{ is_state(trigger.entity_id, 'on')\n   and is_state(prev, 'on')\n   and is_state(night, 'off') }}"},{"action":"switch.turn_on","target":{"entity_id":"{{ night }}"}}],"mode":"parallel"},"blink_indoor_motion_alarm":{"alias":"Blink — Indoor motion alert on the Nest Mini","description":"Repeats a spoken alert on the Nest Mini while an indoor Blink camera - Kitchen or Living Room - has seen motion and the system is armed. Names the room. Keeps going until it is silenced from the Security view, until the camera is un-enrolled, until the system is disarmed, or until 15 minutes have passed.","variables":{"alarm_end_ts":"{{ as_timestamp(now()) + 900 }}","room_id":"{{ trigger.id | default('kitchen', true) }}","room_switch":"switch.{{ room_id }}_camera_motion_detection","room_name":"{{ 'the living room' if room_id == 'living_room' else 'the kitchen' }}"},"triggers":[{"trigger":"state","entity_id":"binary_sensor.kitchen_motion","to":"on","id":"kitchen"},{"trigger":"state","entity_id":"binary_sensor.living_room_motion","to":"on","id":"living_room"}],"conditions":[{"condition":"state","entity_id":"alarm_control_panel.blink_system","state":"armed_away"},{"condition":"template","value_template":"{{ is_state(room_switch, 'on') }}"},{"condition":"state","entity_id":"input_boolean.blink_indoor_alarm_active","state":"off"},{"condition":"state","entity_id":"input_boolean.blink_entry_grace","state":"off"}],"actions":[{"action":"input_boolean.turn_on","target":{"entity_id":"input_boolean.blink_indoor_alarm_active"}},{"action":"media_player.volume_set","continue_on_error":true,"target":{"entity_id":"media_player.nest_mini"},"data":{"volume_level":0.5}},{"repeat":{"while":[{"condition":"state","entity_id":"input_boolean.blink_indoor_alarm_active","state":"on"},{"condition":"template","value_template":"{{ is_state(room_switch, 'on') }}"},{"condition":"state","entity_id":"input_boolean.blink_entry_grace","state":"off"},{"condition":"state","entity_id":"alarm_control_panel.blink_system","state":"armed_away"},{"condition":"template","value_template":"{{ as_timestamp(now()) < alarm_end_ts | float }}"}],"sequence":[{"action":"tts.speak","continue_on_error":true,"target":{"entity_id":"tts.google_translate_en_com"},"data":{"media_player_entity_id":"media_player.nest_mini","message":"Alert. Motion detected in {{ room_name }}."}},{"delay":"00:00:05"}]}},{"action":"input_boolean.turn_off","target":{"entity_id":"input_boolean.blink_indoor_alarm_active"}}],"mode":"single"},"blink_snapshot_on_motion_enable":{"alias":"Blink — Snapshot when motion detection turns on","description":"Takes a fresh picture on a Blink camera as soon as its motion detection is switched on, so its card shows what it is now watching instead of whatever it last captured.","triggers":[{"trigger":"state","entity_id":["switch.garage_camera_motion_detection","switch.kitchen_camera_motion_detection","switch.living_room_camera_motion_detection","switch.yard_camera_motion_detection"],"from":"off","to":"on"}],"actions":[{"action":"script.turn_on","target":{"entity_id":"script.blink_snapshot"},"data":{"variables":{"camera":"{{ trigger.entity_id | replace('switch.', 'camera.')\n   | replace('_camera_motion_detection', '') }}"}}}],"mode":"parallel"},"blink_snapshot_on_motion":{"alias":"Blink — Snapshot on motion","description":"Takes a fresh picture on a Blink camera when it reports motion.","triggers":[{"trigger":"state","entity_id":["binary_sensor.garage_motion","binary_sensor.kitchen_motion","binary_sensor.living_room_motion","binary_sensor.yard_motion"],"from":"off","to":"on"}],"actions":[{"action":"script.turn_on","target":{"entity_id":"script.blink_snapshot"},"data":{"variables":{"camera":"{{ trigger.entity_id | replace('binary_sensor.', 'camera.')\n   | replace('_motion', '') }}"}}}],"mode":"parallel"},"blink_snapshot_on_alarm":{"alias":"Blink — Snapshot every camera when the alarm goes off","description":"When the indoor motion alert starts sounding, takes a fresh picture on every Blink camera, so the whole house is on record at that moment.","variables":{"cams":"{% set ns = namespace(c=[]) %} {% for r in ['garage', 'kitchen', 'living_room', 'yard'] %}\n  {% if not is_state('binary_sensor.' ~ r ~ '_motion', 'on') %}\n    {% set ns.c = ns.c + ['camera.' ~ r] %}\n  {% endif %}\n{% endfor %} {{ ns.c }}"},"triggers":[{"trigger":"state","entity_id":"input_boolean.blink_indoor_alarm_active","from":"off","to":"on"}],"actions":[{"repeat":{"for_each":"{{ cams }}","sequence":[{"action":"script.turn_on","target":{"entity_id":"script.blink_snapshot"},"data":{"variables":{"camera":"{{ repeat.item }}"}}}]}}],"mode":"single"},"away_everyone_out":{"alias":"Away — everyone out","description":"Fires when the last person leaves. Turns off every interior light, both standalone heaters and all three Dysons, enrols all four Blink cameras for motion. Starts script.thermostat_eco_leave, which puts both Nest thermostats in Eco (64/80) five minutes later if the house is still empty. Leaves all outdoor lights alone. Skipped once, and the flag cleared, when input_boolean.babysitter_mode is on - that includes Eco, so the Nests stay where the sitter hold has them.","triggers":[{"trigger":"state","entity_id":["person.tomallison24","person.elena"],"to":"not_home"}],"conditions":[{"condition":"state","entity_id":"person.tomallison24","state":"not_home"},{"condition":"state","entity_id":"person.elena","state":"not_home"}],"actions":[{"if":[{"condition":"state","entity_id":"input_boolean.babysitter_mode","state":"on"}],"then":[{"action":"input_boolean.turn_off","target":{"entity_id":"input_boolean.babysitter_mode"}},{"action":"notify.send_message","target":{"entity_id":"notify.tom_fs_iphone"},"data":{"title":"Babysitter mode used","message":"{{ trigger.to_state.attributes.friendly_name | default('Someone') }} left last. House left as it was - lights, heaters, Dysons and cameras untouched. Next departure is back to normal."}},{"stop":"Babysitter mode consumed - house left as is"}]},{"action":"script.turn_on","continue_on_error":true,"target":{"entity_id":"script.thermostat_eco_leave"}},{"action":"light.turn_off","continue_on_error":true,"target":{"entity_id":["light.side_lamps","light.floor_lamps","light.morocco","light.spotlight","light.living_room_fireplace_lights_socket","light.cocktail_main","light.tv_lamps","light.tian_hao_rgbdeng_dai_kong_zhi_qi_wifi","light.bar_main_light_1","light.kitchen","light.kitchen_fan","light.sofias_lamp","light.tom_lamp","light.elena_lamp"]}},{"action":"climate.turn_off","continue_on_error":true,"target":{"entity_id":["climate.office_heater","climate.mum_dad_heater"]}},{"action":"fan.turn_off","continue_on_error":true,"target":{"entity_id":["fan.m_d_dyson","fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"]}},{"action":"script.turn_on","target":{"entity_id":"script.blink_set_enrolment"},"data":{"variables":{"state":"on","reason":"Away","entities":["switch.yard_camera_motion_detection","switch.garage_camera_motion_detection","switch.kitchen_camera_motion_detection","switch.living_room_camera_motion_detection"]}}},{"action":"alarm_control_panel.alarm_arm_away","continue_on_error":true,"target":{"entity_id":"alarm_control_panel.blink_system"}},{"delay":"00:00:10"},{"action":"notify.send_message","target":{"entity_id":"notify.tom_fs_iphone"},"data":{"title":"House secured","message":"{{ trigger.to_state.attributes.friendly_name | default('Someone') }} left last. Lights, heaters and Dysons off. Cameras watching: {% set on = [\n  'Yard' if is_state('switch.yard_camera_motion_detection', 'on') else none,\n  'Garage' if is_state('switch.garage_camera_motion_detection', 'on') else none,\n  'Kitchen' if is_state('switch.kitchen_camera_motion_detection', 'on') else none,\n  'Living Room' if is_state('switch.living_room_camera_motion_detection', 'on') else none\n] | reject('none') | list %}{{ on | join(', ') if on else 'NONE - check Blink' }}. System {{ 'armed' if is_state('alarm_control_panel.blink_system', 'armed_away') else 'NOT ARMED - check Blink' }}."}}],"mode":"single"},"babysitter_mode_expire_unused":{"alias":"Babysitter — expire unused","description":"Clears input_boolean.babysitter_mode at 04:00 if it was armed but nobody left, so a change of plans cannot leave a later departure unsecured.","triggers":[{"trigger":"time","at":"04:00:00"}],"conditions":[{"condition":"state","entity_id":"input_boolean.babysitter_mode","state":"on"}],"actions":[{"action":"input_boolean.turn_off","target":{"entity_id":"input_boolean.babysitter_mode"}},{"action":"notify.send_message","target":{"entity_id":"notify.tom_fs_iphone"},"data":{"title":"Babysitter mode cleared","message":"It was still armed at 04:00 and nobody left, so the next departure will secure the house as normal."}}],"mode":"single"},"home_first_one_back":{"alias":"Home — first one back","description":"Fires when the first person gets home and immediately stands the Garage, Kitchen and Living Room cameras down - no confirmation needed. The Yard keeps watching and the sync module stays armed either way.","triggers":[{"trigger":"state","entity_id":["person.tomallison24","person.elena"],"to":"home"}],"conditions":[{"condition":"template","value_template":"{{ [states('person.tomallison24'), states('person.elena')]\n   | select('eq', 'home') | list | count == 1 }}"}],"actions":[{"action":"input_boolean.turn_on","target":{"entity_id":"input_boolean.blink_entry_grace"}},{"action":"script.turn_on","target":{"entity_id":"script.blink_set_enrolment"},"data":{"variables":{"state":"off","reason":"Home","entities":["switch.garage_camera_motion_detection","switch.kitchen_camera_motion_detection","switch.living_room_camera_motion_detection"]}}},{"delay":"00:00:10"},{"action":"notify.send_message","continue_on_error":true,"target":{"entity_id":"notify.tom_fs_iphone"},"data":{"title":"Indoor cameras stood down","message":"{{ trigger.to_state.attributes.friendly_name | default('Someone') }} arrived. Stood down: {% set off = [\n  'Garage' if is_state('switch.garage_camera_motion_detection', 'off') else none,\n  'Kitchen' if is_state('switch.kitchen_camera_motion_detection', 'off') else none,\n  'Living Room' if is_state('switch.living_room_camera_motion_detection', 'off') else none\n] | reject('none') | list %}{{ off | join(', ') if off else 'NONE - check Blink' }}. {{ 'Yard still watching.' if is_state('switch.yard_camera_motion_detection', 'on') else 'Yard NOT watching - check Blink.' }}"}},{"action":"input_boolean.turn_off","target":{"entity_id":"input_boolean.blink_entry_grace"}}],"mode":"single"},"moms_awake_weekday_reminder":{"alias":"Mom's Awake — weekday reminder to Elena","description":"Sends Elena a reminder at 05:55 on weekdays to run the Mom's Awake routine, unless she has already run it today. A notification only - nothing in the house changes.","triggers":[{"trigger":"time","at":"05:55:00"}],"conditions":[{"condition":"time","weekday":["mon","tue","wed","thu","fri"]},{"condition":"template","value_template":"{{ state_attr('automation.mom_s_awake', 'last_triggered') is none\n   or (state_attr('automation.mom_s_awake', 'last_triggered')\n       | as_local).date() != now().date() }}"}],"actions":[{"action":"notify.send_message","target":{"entity_id":"notify.elenas_iphone"},"data":{"title":"Mom's Awake","message":"Remember to run Mom's Awake routine!"}}],"mode":"single"},"signal_lr_setpoint_mirror":{"alias":"Signal — thermostat setpoint mirror","description":"Copies each thermostat's real setpoints into its TF1 card's shown-setpoint helpers whenever they change outside the card (app, schedule, mode switch, the Office -> Windmill sync) - but not while that unit's push script is still settling a change made on the card, so the card never jumps back. Living Room + Office Nests and the Windmill AC.","triggers":[{"trigger":"state","entity_id":["climate.living_room_living_room","climate.office_office","climate.windmill_ac"],"attribute":"temperature"},{"trigger":"state","entity_id":["climate.living_room_living_room","climate.office_office"],"attribute":"target_temp_low"},{"trigger":"state","entity_id":["climate.living_room_living_room","climate.office_office"],"attribute":"target_temp_high"},{"trigger":"state","entity_id":["climate.living_room_living_room","climate.office_office","climate.windmill_ac"]},{"trigger":"homeassistant","event":"start"},{"trigger":"event","event_type":"automation_reloaded"}],"actions":[{"variables":{"units":[{"climate":"climate.living_room_living_room","push":"script.signal_lr_push_setpoint","set":"input_number.signal_lr_set","low":"input_number.signal_lr_set_low","high":"input_number.signal_lr_set_high","mode":"","fan":""},{"climate":"climate.office_office","push":"script.signal_of_push_setpoint","set":"input_number.signal_of_set","low":"input_number.signal_of_set_low","high":"input_number.signal_of_set_high","mode":"","fan":""},{"climate":"climate.windmill_ac","push":"script.signal_wm_push_setpoint","set":"input_number.signal_wm_set","low":"","high":"","mode":"input_text.signal_wm_mode","fan":"input_text.signal_wm_fan"}],"only":"{{ trigger.entity_id if trigger is defined and trigger.entity_id is defined else '' }}"}},{"repeat":{"for_each":"{{ units if not only else (units | selectattr('climate', 'eq', only) | list) }}","sequence":[{"if":[{"condition":"template","value_template":"{{ is_state(repeat.item.push, 'off') and states(repeat.item.climate) not in ['unknown', 'unavailable'] }}"}],"then":[{"variables":{"a":{"temperature":"{{ state_attr(repeat.item.climate, 'temperature') }}","target_temp_low":"{{ state_attr(repeat.item.climate, 'target_temp_low') }}","target_temp_high":"{{ state_attr(repeat.item.climate, 'target_temp_high') }}","fan_mode":"{{ state_attr(repeat.item.climate, 'fan_mode') }}"}}},{"if":[{"condition":"template","value_template":"{{ a.temperature is number }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"{{ repeat.item.set }}"},"data":{"value":"{{ a.temperature | round(0) }}"}}]},{"if":[{"condition":"template","value_template":"{{ repeat.item.low != '' and a.target_temp_low is number and a.target_temp_high is number }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"{{ repeat.item.low }}"},"data":{"value":"{{ a.target_temp_low | round(0) }}"}},{"action":"input_number.set_value","target":{"entity_id":"{{ repeat.item.high }}"},"data":{"value":"{{ a.target_temp_high | round(0) }}"}}]},{"if":[{"condition":"template","value_template":"{{ repeat.item.mode != '' }}"}],"then":[{"action":"input_text.set_value","target":{"entity_id":"{{ repeat.item.mode }}"},"data":{"value":"{{ states(repeat.item.climate) }}"}}]},{"if":[{"condition":"template","value_template":"{{ repeat.item.fan != '' and a.fan_mode is string and a.fan_mode != '' }}"}],"then":[{"action":"input_text.set_value","target":{"entity_id":"{{ repeat.item.fan }}"},"data":{"value":"{{ a.fan_mode }}"}}]}]}]}}],"mode":"queued"},"signal_dyson_filter_low":{"alias":"Signal — Dyson: filter low","description":"Pushes to Tom's iPhone, Elena's iPhone and the Pixel Tablet once when any Dyson filter drops below 10%.","variables":{"info":"{{ {'sensor.sofias_dyson_filter_life_percent':\n      {'title': \"Sofia's Dyson · Filter\", 'raw': 'sensor.sofias_dyson_filter_life', 'reset': true},\n    'sensor.olivias_dyson_filter_life_percent':\n      {'title': \"Olivia's Dyson · Filter\", 'raw': 'sensor.olivia_s_bedroom_olivias_dyson_filter_life', 'reset': true},\n    'sensor.m_d_dyson_hepa_filter_life':\n      {'title': 'M&D Dyson · HEPA Filter', 'raw': 'sensor.m_d_dyson_hepa_filter_life', 'reset': false},\n    'sensor.m_d_dyson_carbon_filter_life':\n      {'title': 'M&D Dyson · Carbon Filter', 'raw': 'sensor.m_d_dyson_carbon_filter_life', 'reset': false}\n   }[trigger.entity_id] }}","pct":"{{ states(trigger.entity_id) | float(0) | round(0) | int }}"},"triggers":[{"trigger":"numeric_state","entity_id":["sensor.sofias_dyson_filter_life_percent","sensor.olivias_dyson_filter_life_percent","sensor.m_d_dyson_hepa_filter_life","sensor.m_d_dyson_carbon_filter_life"],"below":10,"for":"00:10:00"}],"conditions":[{"condition":"template","value_template":"{{ states(info.raw) | is_number }}"}],"actions":[{"repeat":{"for_each":["notify.tom_fs_iphone","notify.elenas_iphone","notify.pixel_tablet"],"sequence":[{"action":"notify.send_message","continue_on_error":true,"target":{"entity_id":"{{ repeat.item }}"},"data":{"title":"{{ info.title }} at {{ pct }}%","message":"{{ 'Time to order a replacement filter. Once it is in, hold the Filter tile on the Dyson card to reset the counter.'\n   if info.reset else 'Time to order a replacement filter.' }}"}}]}}],"mode":"queued"},"signal_dyson_air_boost":{"alias":"Signal — Dyson: Air Boost","description":"Switches a running Dyson to Auto after five minutes of poor air, between 07:00 and 19:00, and flags it so Air Boost end can put it back.","triggers":[{"trigger":"template","value_template":"{{ states('sensor.sofias_dyson_air_quality_index') | float(0) > 6\n   or states('sensor.sofias_dyson_volatile_organic_compounds_index') | float(0) > 6 }}","for":"00:05:00"},{"trigger":"template","value_template":"{{ states('sensor.olivia_s_bedroom_olivias_dyson_air_quality_index') | float(0) > 6\n   or states('sensor.olivia_s_bedroom_olivias_dyson_volatile_organic_compounds_index') | float(0) > 6 }}","for":"00:05:00"},{"trigger":"template","value_template":"{{ states('sensor.m_d_dyson_pm_2_5') | float(0) > 35.4\n   or states('sensor.m_d_dyson_pm_10') | float(0) > 154\n   or states('sensor.m_d_dyson_nitrogen_dioxide_index') | float(0) > 6\n   or states('sensor.m_d_dyson_volatile_organic_compounds_index') | float(0) > 6 }}","for":"00:05:00"},{"trigger":"time","at":"07:00:00"},{"trigger":"state","entity_id":["fan.m_d_dyson","fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"to":"on","for":"00:05:00"}],"conditions":[{"condition":"time","after":"07:00:00","before":"19:00:00"}],"actions":[{"variables":{"poor":{"so":"{{ states('sensor.sofias_dyson_air_quality_index') | float(0) > 6\n   or states('sensor.sofias_dyson_volatile_organic_compounds_index') | float(0) > 6 }}","ol":"{{ states('sensor.olivia_s_bedroom_olivias_dyson_air_quality_index') | float(0) > 6\n   or states('sensor.olivia_s_bedroom_olivias_dyson_volatile_organic_compounds_index') | float(0) > 6 }}","md":"{{ states('sensor.m_d_dyson_pm_2_5') | float(0) > 35.4\n   or states('sensor.m_d_dyson_pm_10') | float(0) > 154\n   or states('sensor.m_d_dyson_nitrogen_dioxide_index') | float(0) > 6\n   or states('sensor.m_d_dyson_volatile_organic_compounds_index') | float(0) > 6 }}"}}},{"repeat":{"for_each":[{"key":"so","fan":"fan.sofias_dyson","flag":"input_boolean.signal_dyson_sofia_boost"},{"key":"ol","fan":"fan.olivia_s_bedroom_olivias_dyson","flag":"input_boolean.signal_dyson_olivia_boost"},{"key":"md","fan":"fan.m_d_dyson","flag":"input_boolean.signal_dyson_md_boost"}],"sequence":[{"if":[{"condition":"template","value_template":"{{ (poor[repeat.item.key] | string | lower) == 'true'\n   and is_state(repeat.item.fan, 'on')\n   and state_attr(repeat.item.fan, 'preset_mode') != 'Auto'\n   and not is_state(repeat.item.flag, 'on') }}"}],"then":[{"action":"input_boolean.turn_on","target":{"entity_id":"{{ repeat.item.flag }}"}},{"action":"fan.set_preset_mode","target":{"entity_id":"{{ repeat.item.fan }}"},"data":{"preset_mode":"Auto"}}]}]}}],"mode":"queued"},"signal_dyson_air_boost_end":{"alias":"Signal — Dyson: Air Boost end","description":"Restores a boosted Dyson's previous speed once the air recovers (ten minutes out of Poor) or at 19:00; drops the flag without restoring if the unit was switched off or taken out of Auto by hand.","triggers":[{"trigger":"template","id":"so","value_template":"{{ not (states('sensor.sofias_dyson_air_quality_index') | float(0) > 6\n   or states('sensor.sofias_dyson_volatile_organic_compounds_index') | float(0) > 6) }}","for":"00:10:00"},{"trigger":"template","id":"ol","value_template":"{{ not (states('sensor.olivia_s_bedroom_olivias_dyson_air_quality_index') | float(0) > 6\n   or states('sensor.olivia_s_bedroom_olivias_dyson_volatile_organic_compounds_index') | float(0) > 6) }}","for":"00:10:00"},{"trigger":"template","id":"md","value_template":"{{ not (states('sensor.m_d_dyson_pm_2_5') | float(0) > 35.4\n   or states('sensor.m_d_dyson_pm_10') | float(0) > 154\n   or states('sensor.m_d_dyson_nitrogen_dioxide_index') | float(0) > 6\n   or states('sensor.m_d_dyson_volatile_organic_compounds_index') | float(0) > 6) }}","for":"00:10:00"},{"trigger":"time","id":"window","at":"19:00:00"},{"trigger":"state","id":"manual","entity_id":["fan.m_d_dyson","fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"to":"off"},{"trigger":"state","id":"manual","entity_id":["fan.m_d_dyson","fan.sofias_dyson","fan.olivia_s_bedroom_olivias_dyson"],"attribute":"preset_mode","from":"Auto"}],"actions":[{"repeat":{"for_each":[{"key":"so","fan":"fan.sofias_dyson","flag":"input_boolean.signal_dyson_sofia_boost","prev":"input_number.sofia_s_dyson_previous_speed"},{"key":"ol","fan":"fan.olivia_s_bedroom_olivias_dyson","flag":"input_boolean.signal_dyson_olivia_boost","prev":"input_number.olivia_s_dyson_previous_speed"},{"key":"md","fan":"fan.m_d_dyson","flag":"input_boolean.signal_dyson_md_boost","prev":"input_number.m_d_dyson_previous_speed"}],"sequence":[{"if":[{"condition":"template","value_template":"{{ is_state(repeat.item.flag, 'on') }}"}],"then":[{"choose":[{"conditions":[{"condition":"template","value_template":"{{ not is_state(repeat.item.fan, 'on')\n   or state_attr(repeat.item.fan, 'preset_mode') != 'Auto' }}"}],"sequence":[{"action":"input_boolean.turn_off","target":{"entity_id":"{{ repeat.item.flag }}"}}]},{"conditions":[{"condition":"template","value_template":"{{ trigger.id in [repeat.item.key, 'window'] }}"}],"sequence":[{"action":"fan.set_percentage","target":{"entity_id":"{{ repeat.item.fan }}"},"data":{"percentage":"{{ states(repeat.item.prev) | int(20) }}"}},{"delay":"00:00:08"},{"action":"input_boolean.turn_off","target":{"entity_id":"{{ repeat.item.flag }}"}}]}]}]}]}}],"mode":"queued"},"signal_move_battery_low":{"alias":"Signal — Sonos Move battery low","description":"Push to Tom when the Move drops below 20% and is not charging.","triggers":[{"trigger":"numeric_state","entity_id":"sensor.move_battery","below":20}],"conditions":[{"condition":"state","entity_id":"binary_sensor.move_charging","state":"off"}],"actions":[{"action":"notify.send_message","target":{"entity_id":"notify.tom_fs_iphone"},"data":{"title":"Sonos Move","message":"Battery at {{ states('sensor.move_battery') | int(0) }}% and not on its base."}}],"mode":"single"},"signal_move_off_base":{"alias":"Signal — Sonos Move left off its base","description":"Push to Tom when the Move has been off its base for two hours with under half its battery.","triggers":[{"trigger":"state","entity_id":"binary_sensor.move_charging","to":"off","for":"02:00:00"}],"conditions":[{"condition":"numeric_state","entity_id":"sensor.move_battery","below":50}],"actions":[{"action":"notify.send_message","target":{"entity_id":"notify.tom_fs_iphone"},"data":{"title":"Sonos Move","message":"Off its base for 2 hours - battery at {{ states('sensor.move_battery') | int(0) }}%."}}],"mode":"single"},"signal_fold_idle_rooms":{"alias":"Signal — fold cards left open","description":"Folds any Signal room card (Favorites, Climate, Lights, Media, Devices, Security) that has been open for 10 minutes; the TV remotes wait until the TV has been off for 10 minutes.","triggers":[{"trigger":"state","entity_id":["media_player.living_room_samsung_tv","media_player.living_room_living_room"],"to":["off","standby","unavailable"],"for":"00:10:00","id":"tv_off"},{"trigger":"state","entity_id":["input_boolean.signal_lights_room_living","input_boolean.signal_lights_room_lounge","input_boolean.signal_lights_room_kitchen","input_boolean.signal_lights_room_sofia","input_boolean.signal_lights_room_md","input_boolean.signal_lights_room_outdoor","input_boolean.signal_lights_open_energy","input_boolean.signal_lights_master_bedroom","input_boolean.signal_weather_expanded","input_boolean.signal_activity_expanded","input_boolean.signal_new_expanded"],"to":"on","for":"00:10:00"},{"trigger":"state","entity_id":["input_boolean.signal_media_kitchen_sonos_vol","input_boolean.signal_media_lounge_sonos_vol","input_boolean.signal_media_office_sonos_vol","input_boolean.signal_media_arc_sub_vol","input_boolean.signal_media_move_vol","input_boolean.signal_media_atv_vol","input_boolean.signal_media_tv_vol","input_boolean.signal_media_nest_vol","input_boolean.signal_climate_open_lr","input_boolean.signal_climate_open_of","input_boolean.signal_climate_open_wm","input_boolean.signal_climate_open_sofia","input_boolean.signal_climate_open_olivia","input_boolean.signal_climate_open_md","input_boolean.signal_climate_open_oheat","input_boolean.signal_climate_open_mdheat","input_boolean.signal_devices_open_shark","input_boolean.signal_devices_open_hatch","input_boolean.signal_dh_cube","input_boolean.signal_dh_upstairs","input_boolean.signal_devices_open_blinds","input_boolean.signal_devices_open_printer","input_boolean.signal_devices_open_energy","input_boolean.signal_climate_open_energy","input_boolean.signal_media_open_energy","input_boolean.signal_security_open_yard","input_boolean.signal_security_open_garage","input_boolean.signal_security_open_kitchen","input_boolean.signal_security_open_living_room"],"to":"on","for":"00:10:00"}],"actions":[{"variables":{"remotes":["input_boolean.signal_media_atv_vol","input_boolean.signal_media_tv_vol"],"tv_on":"{{ states('media_player.living_room_samsung_tv') in ['on', 'idle', 'paused', 'playing']\n   or states('media_player.living_room_living_room') in ['playing', 'paused'] }}"}},{"choose":[{"conditions":[{"condition":"trigger","id":"tv_off"}],"sequence":[{"condition":"template","value_template":"{{ not tv_on and remotes | select('is_state', 'on') | list | count > 0 }}"},{"action":"input_boolean.turn_off","target":{"entity_id":"{{ remotes | select('is_state', 'on') | list }}"}}]}],"default":[{"condition":"template","value_template":"{{ not (trigger.entity_id in remotes and tv_on) }}"},{"action":"input_boolean.turn_off","target":{"entity_id":"{{ trigger.entity_id }}"}}]}],"mode":"parallel"},"signal_fold_drawers_with_room":{"alias":"Signal — close drawers with their room","description":"When a Signal card folds, its inner drawers (group pills, More details, Dyson / heater / Sonos / Shark / Hatch / blinds / dehumidifier drawers) close with it.","triggers":[{"trigger":"state","entity_id":["input_boolean.signal_lights_room_living","input_boolean.signal_lights_room_lounge","input_boolean.signal_lights_room_kitchen","input_boolean.signal_lights_room_md","input_boolean.signal_lights_room_outdoor","input_boolean.signal_media_kitchen_sonos_vol","input_boolean.signal_media_lounge_sonos_vol","input_boolean.signal_media_office_sonos_vol","input_boolean.signal_media_arc_sub_vol","input_boolean.signal_media_move_vol","input_boolean.signal_media_atv_vol","input_boolean.signal_media_tv_vol","input_boolean.signal_media_nest_vol","input_boolean.signal_climate_open_sofia","input_boolean.signal_climate_open_olivia","input_boolean.signal_climate_open_md","input_boolean.signal_climate_open_oheat","input_boolean.signal_climate_open_mdheat","input_boolean.signal_devices_open_shark","input_boolean.signal_devices_open_hatch","input_boolean.signal_devices_open_blinds","input_boolean.signal_dh_cube","input_boolean.signal_dh_upstairs"],"to":"off"}],"actions":[{"variables":{"drawers":{"input_boolean.signal_lights_room_living":["input_boolean.signal_lights_floor_lamps","input_boolean.signal_lights_morocco"],"input_boolean.signal_lights_room_lounge":["input_boolean.signal_lights_cocktail_main","input_boolean.signal_lights_tv_lamps","input_boolean.signal_lights_tv_strip","input_boolean.signal_lights_side_lamps"],"input_boolean.signal_lights_room_kitchen":["input_boolean.signal_lights_kitchen","input_boolean.signal_lights_kitchen_fan"],"input_boolean.signal_lights_room_md":["input_boolean.signal_lights_master_bedroom"],"input_boolean.signal_lights_room_outdoor":["input_boolean.signal_lights_outdoor_front"],"input_boolean.signal_media_kitchen_sonos_vol":["input_boolean.signal_media_kitchen_sonos","input_boolean.signal_media_kitchen_sonos_more"],"input_boolean.signal_media_lounge_sonos_vol":["input_boolean.signal_media_lounge_sonos","input_boolean.signal_media_lounge_sonos_more"],"input_boolean.signal_media_office_sonos_vol":["input_boolean.signal_media_office_sonos","input_boolean.signal_media_office_sonos_more"],"input_boolean.signal_media_arc_sub_vol":["input_boolean.signal_media_arc_sub","input_boolean.signal_media_arc_sub_more"],"input_boolean.signal_media_move_vol":["input_boolean.signal_media_move","input_boolean.signal_media_move_more"],"input_boolean.signal_media_atv_vol":["input_boolean.signal_media_atv"],"input_boolean.signal_media_tv_vol":["input_boolean.signal_media_tv"],"input_boolean.signal_media_nest_vol":["input_boolean.signal_media_nest"],"input_boolean.signal_climate_open_sofia":["input_boolean.signal_dyson_sofia"],"input_boolean.signal_climate_open_olivia":["input_boolean.signal_dyson_olivia"],"input_boolean.signal_climate_open_md":["input_boolean.signal_dyson_md"],"input_boolean.signal_climate_open_oheat":["input_boolean.signal_heater_office"],"input_boolean.signal_climate_open_mdheat":["input_boolean.signal_heater_md"],"input_boolean.signal_devices_open_shark":["input_boolean.signal_vacuum_shark"],"input_boolean.signal_devices_open_hatch":["input_boolean.signal_hatch_olivia"],"input_boolean.signal_devices_open_blinds":["input_boolean.signal_blinds_office"],"input_boolean.signal_dh_cube":["input_boolean.signal_dh_cube_more"],"input_boolean.signal_dh_upstairs":["input_boolean.signal_dh_upstairs_more"]},"open":"{{ drawers.get(trigger.entity_id, []) | select('is_state', 'on') | list }}"}},{"condition":"template","value_template":"{{ open | count > 0 }}"},{"action":"input_boolean.turn_off","target":{"entity_id":"{{ open }}"}}],"mode":"parallel"},"1790421600000":{"alias":"Hatch - Olivia's bedtime","description":"19:00 every night - White Noise at 30 %, Hatch clock and night light off (script.hatch_bedtime). HA runs Olivia's Hatch on its own since 2026-09-27 - Tom deleted the Hatch app's routines, which used to start bedtime at 19:00 (this ran at 19:00:30 to land after them).","triggers":[{"trigger":"time","at":"19:00:00"}],"conditions":[],"actions":[{"action":"script.hatch_bedtime","data":{"light":"off"}}],"mode":"single"},"1790421600002":{"alias":"Hatch - Olivia's morning off","description":"07:30 every day - the Hatch switches off (sound and light), an hour after wake-up, as the Hatch app routine did. Skipped if it is already off. media_stop turns the whole Rest off, light included.","triggers":[{"trigger":"time","at":"07:30:00"}],"conditions":[{"condition":"or","conditions":[{"condition":"state","entity_id":"media_player.olivias_hatch_media_player","state":"playing"},{"condition":"state","entity_id":"light.olivias_hatch_light","state":"on"}]}],"actions":[{"action":"media_player.media_stop","target":{"entity_id":"media_player.olivias_hatch_media_player"}}],"mode":"single"},"morning_lights_off_0800":{"alias":"Morning Lights — All Off at 08:00","description":"08:00 every day - switches off every indoor house light, the TV strip, fireplace socket and Elena's lamp included. Same list as \"Away — everyone out\", which is the \"all interior lights\" set. A light that is already off is a no-op.\nOutdoor lights are not here: the deck goes off with Goodnight, the front at 22:30 and the garage at sunrise-3h. Manual Off Suppresses cannot be tripped by this - it only listens while the sun is down and more than 3h from sunrise, and 08:00 is daylight all year.","triggers":[{"trigger":"time","at":"08:00:00"}],"conditions":[],"actions":[{"action":"light.turn_off","continue_on_error":true,"target":{"entity_id":["light.side_lamps","light.floor_lamps","light.morocco","light.spotlight","light.living_room_fireplace_lights_socket","light.cocktail_main","light.tv_lamps","light.tian_hao_rgbdeng_dai_kong_zhi_qi_wifi","light.bar_main_light_1","light.kitchen","light.kitchen_fan","light.sofias_lamp","light.tom_lamp","light.elena_lamp"]}}],"mode":"single"},"thermostat_schedule":{"alias":"Thermostat — daily schedule","description":"Living Room 06:00 / 08:00 (Mon-Fri only) / 17:00, Office 07:00 / 19:00. Each step records its profile and applies it unless Eco or the sitter hold is blocking the Nests (see script.thermostat_apply). Goodnight is the night step and lives in the Goodnight automation.","triggers":[{"trigger":"time","at":"06:00:00","id":"lr_morning"},{"trigger":"time","at":"08:00:00","id":"lr_day"},{"trigger":"time","at":"17:00:00","id":"lr_evening"},{"trigger":"time","at":"07:00:00","id":"of_morning"},{"trigger":"time","at":"19:00:00","id":"of_evening"}],"conditions":[{"condition":"template","value_template":"{{ trigger.id != 'lr_day' or now().weekday() < 5 }}"}],"actions":[{"action":"script.thermostat_apply","data":{"rooms":"{{ [trigger.id.split('_')[0]] }}","phase":"{{ trigger.id.split('_')[1] }}"}}],"mode":"queued"},"thermostat_someone_home":{"alias":"Thermostat — someone home","description":"Ends Eco when a person arrives and puts both Nests back on the profile the schedule says is current (unless the sitter hold is on).","triggers":[{"trigger":"state","entity_id":["person.tomallison24","person.elena"],"to":"home"}],"conditions":[{"condition":"state","entity_id":"input_boolean.thermostat_eco","state":"on"}],"actions":[{"action":"input_boolean.turn_off","target":{"entity_id":"input_boolean.thermostat_eco"}},{"action":"script.thermostat_apply"}],"mode":"single"},"thermostat_recover":{"alias":"Thermostat — re-apply after a restart or outage","description":"A time trigger that fires while HA is down or the Nest is unreachable is not replayed. One minute after HA starts, or after either Nest comes back from unavailable, re-apply what the Nests should be on.","triggers":[{"trigger":"homeassistant","event":"start"},{"trigger":"state","entity_id":["climate.living_room_living_room","climate.office_office"],"from":"unavailable"}],"conditions":[],"actions":[{"delay":"00:01:00"},{"action":"script.thermostat_apply"}],"mode":"single"},"thermostat_hold_release_0400":{"alias":"Thermostat — release hold at 04:00","description":"Safety net. The sitter hold ends only with the pill or Goodnight; if neither happened, it lets go at 04:00 so the schedule is not frozen all day. Runs 30 s after \"Babysitter — expire unused\" so that one still sees its flag.","triggers":[{"trigger":"time","at":"04:00:30"}],"conditions":[{"condition":"state","entity_id":"input_boolean.thermostat_hold","state":"on"}],"actions":[{"action":"script.thermostat_sitter_release"},{"action":"notify.send_message","continue_on_error":true,"target":{"entity_id":"notify.tom_fs_iphone"},"data":{"title":"Thermostat hold released","message":"The sitter hold was still on at 04:00, so both thermostats are back on the schedule."}}],"mode":"single"},"signal_calendar_reset":{"alias":"Signal — Calendar back to today","description":"Puts the Calendar view back on this month and today, at midnight and 10 minutes after anyone last paged the month or picked a day.","triggers":[{"trigger":"time","at":"00:00:05"},{"trigger":"state","entity_id":["input_number.signal_calendar_month","input_datetime.signal_calendar_date"],"for":"00:10:00"}],"conditions":[],"actions":[{"if":[{"condition":"template","value_template":"{{ states('input_number.signal_calendar_month') | float(0) != 0 }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_calendar_month"},"data":{"value":0}}]},{"if":[{"condition":"template","value_template":"{{ states('input_datetime.signal_calendar_date') != now().strftime('%Y-%m-%d') }}"}],"then":[{"action":"input_datetime.set_datetime","target":{"entity_id":"input_datetime.signal_calendar_date"},"data":{"date":"{{ now().strftime('%Y-%m-%d') }}"}}]}],"mode":"single"},"signal_calendar_form_end_follows":{"alias":"Signal — Calendar form keeps end after start","description":"In the Calendar's Add event form, changing Starts sets Ends to an hour later, and moving the Date past the all-day end date moves that too.","triggers":[{"trigger":"state","entity_id":"input_datetime.signal_cal_new_start","id":"start"},{"trigger":"state","entity_id":"input_datetime.signal_cal_new_date","id":"date"}],"conditions":[{"condition":"template","value_template":"{{ trigger.to_state.state not in ['unknown', 'unavailable', ''] }}"}],"actions":[{"choose":[{"conditions":[{"condition":"trigger","id":"start"}],"sequence":[{"action":"input_datetime.set_datetime","target":{"entity_id":"input_datetime.signal_cal_new_end"},"data":{"time":"{% set s = strptime(trigger.to_state.state, '%H:%M:%S') %} {{ '23:59:00' if s.hour >= 23 else (s + timedelta(hours=1)).strftime('%H:%M:%S') }}"}}]},{"conditions":[{"condition":"trigger","id":"date"},{"condition":"template","value_template":"{{ states('input_datetime.signal_cal_new_end_date') in ['unknown', 'unavailable', '']\n   or states('input_datetime.signal_cal_new_end_date') < trigger.to_state.state }}"}],"sequence":[{"action":"input_datetime.set_datetime","target":{"entity_id":"input_datetime.signal_cal_new_end_date"},"data":{"date":"{{ trigger.to_state.state }}"}}]}]}],"mode":"queued"},"signal_changelog_seen":{"alias":"Signal — New! list read","description":"Records when the changelog list on Favorites was opened, so the New! badge counts only what is newer (input_number.signal_changelog_seen).","triggers":[{"trigger":"state","entity_id":"input_boolean.signal_new_expanded","to":"on"}],"actions":[{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_changelog_seen"},"data":{"value":"{{ now().timestamp() | int }}"}}],"mode":"single"},"heater_countdown":{"alias":"Heaters — countdown","description":"The heater countdown on Signal's heater cards and in the aOS Home app (1, 2, 4 or 8 h). When a heater's countdown timer ends, that heater turns off; when a heater is turned off any other way, its countdown is cancelled. The Tuya app's own countdown is not in Home Assistant (the Tuya integration has none for a heater), so these timers stand in for it - see HEATER COUNTDOWNS in configuration.yaml. A countdown that ran out while HA was down still fires timer.finished on start-up (restore: true), so the heater still goes off.","triggers":[{"trigger":"event","event_type":"timer.finished","event_data":{"entity_id":"timer.office_heater_countdown"},"id":"end","variables":{"heater":"climate.office_heater","countdown":"timer.office_heater_countdown"}},{"trigger":"event","event_type":"timer.finished","event_data":{"entity_id":"timer.md_heater_countdown"},"id":"end","variables":{"heater":"climate.mum_dad_heater","countdown":"timer.md_heater_countdown"}},{"trigger":"state","entity_id":"climate.office_heater","to":"off","id":"turned_off","variables":{"heater":"climate.office_heater","countdown":"timer.office_heater_countdown"}},{"trigger":"state","entity_id":"climate.mum_dad_heater","to":"off","id":"turned_off","variables":{"heater":"climate.mum_dad_heater","countdown":"timer.md_heater_countdown"}}],"conditions":[],"actions":[{"choose":[{"conditions":[{"condition":"trigger","id":"end"}],"sequence":[{"action":"climate.set_hvac_mode","target":{"entity_id":"{{ heater }}"},"data":{"hvac_mode":"off"}}]},{"conditions":[{"condition":"trigger","id":"turned_off"},{"condition":"template","value_template":"{{ states(countdown) in ['active', 'paused'] }}"}],"sequence":[{"action":"timer.cancel","target":{"entity_id":"{{ countdown }}"}}]}]}],"mode":"queued"},"olivia_dyson_early_morning_warmup":{"alias":"Dyson — Olivia's early-morning warm-up","description":"If Olivia's Dyson is in heat mode, sets it to 73°F at 04:00 and 74°F at 05:00, whatever its target was.","triggers":[{"trigger":"time","at":"04:00:00","variables":{"target":73}},{"trigger":"time","at":"05:00:00","variables":{"target":74}}],"conditions":[{"condition":"state","entity_id":"climate.olivia_s_bedroom_olivias_dyson","state":"heat"}],"actions":[{"action":"climate.set_temperature","target":{"entity_id":"climate.olivia_s_bedroom_olivias_dyson"},"data":{"temperature":"{{ target }}"}}],"mode":"single"}};
const HA_SCRIPTS = {"blink_snapshot":{"alias":"Blink Snapshot","description":"Asks one Blink camera to capture a fresh thumbnail now, then pulls the new image into HA.","sequence":[{"action":"blink.trigger_camera","target":{"entity_id":"{{ camera }}"}},{"delay":{"seconds":8}},{"action":"homeassistant.update_entity","target":{"entity_id":"{{ camera }}"}}],"mode":"parallel"},"thermostat_apply":{"alias":"Thermostat — apply profile","description":"Puts the Living Room and Office Nests on the setpoints they should have right now. Optional phase = the profile a timed step or Goodnight has just moved to (recorded first, always). Precedence: HOLD (sitter) leaves the Nests alone, then ECO (house empty), then the stored profile.","sequence":[{"variables":{"room_list":"{{ rooms | default(['lr', 'of']) }}","new_phase":"{{ phase | default('') }}","cfg":{"lr":{"climate":"climate.living_room_living_room","phase":"input_select.thermostat_lr_phase","eco":[64,80],"profiles":{"morning":[70,78],"day":[68,80],"evening":[70,78],"night":[64,82]}},"of":{"climate":"climate.office_office","phase":"input_select.thermostat_of_phase","eco":[64,80],"profiles":{"morning":[68,80],"evening":[68,78],"night":[64,78]}}}}},{"repeat":{"for_each":"{{ room_list }}","sequence":[{"if":[{"condition":"template","value_template":"{{ new_phase in cfg[repeat.item].profiles }}"}],"then":[{"action":"input_select.select_option","target":{"entity_id":"{{ cfg[repeat.item].phase }}"},"data":{"option":"{{ new_phase }}"}}]}]}},{"if":[{"condition":"state","entity_id":"input_boolean.thermostat_hold","state":"on"}],"then":[{"stop":"Sitter hold is on - Nests left as they are"}]},{"repeat":{"for_each":"{{ room_list }}","sequence":[{"variables":{"c":"{{ cfg[repeat.item] }}","tgt":"{{ c.eco if is_state('input_boolean.thermostat_eco', 'on')\n   else c.profiles.get(states(c.phase), c.profiles['morning']) }}"}},{"wait_template":"{{ states(c.climate) not in ['unavailable', 'unknown'] }}","timeout":"00:02:00","continue_on_timeout":true},{"if":[{"condition":"template","value_template":"{{ states(c.climate) not in ['unavailable', 'unknown'] }}"}],"then":[{"if":[{"condition":"template","value_template":"{{ state_attr(c.climate, 'preset_mode') == 'eco' }}"}],"then":[{"action":"climate.set_preset_mode","continue_on_error":true,"target":{"entity_id":"{{ c.climate }}"},"data":{"preset_mode":"none"}},{"delay":"00:00:03"}]},{"if":[{"condition":"template","value_template":"{{ not (is_state(c.climate, 'heat_cool')\n        and state_attr(c.climate, 'target_temp_low') | float(0) == tgt[0]\n        and state_attr(c.climate, 'target_temp_high') | float(0) == tgt[1]) }}"}],"then":[{"action":"climate.set_temperature","continue_on_error":true,"target":{"entity_id":"{{ c.climate }}"},"data":{"hvac_mode":"heat_cool","target_temp_low":"{{ tgt[0] }}","target_temp_high":"{{ tgt[1] }}"}}]}]}]}}],"mode":"queued"},"thermostat_eco_leave":{"alias":"Thermostat — Eco after the last person leaves","description":"Five minutes after \"Away — everyone out\" reaches its Eco step, puts both Nests in Eco (64/80) if the house is still empty.","sequence":[{"delay":"00:05:00"},{"condition":"state","entity_id":"person.tomallison24","state":"not_home"},{"condition":"state","entity_id":"person.elena","state":"not_home"},{"condition":"state","entity_id":"input_boolean.thermostat_hold","state":"off"},{"action":"input_boolean.turn_on","target":{"entity_id":"input_boolean.thermostat_eco"}},{"action":"script.thermostat_apply"}],"mode":"single"},"thermostat_sitter_release":{"alias":"Thermostat — release sitter hold","description":"Ends the sitter hold (and cancels the camera one-shot if it is still armed), then puts the Nests on what the schedule says now - or Eco if the house is empty.","sequence":[{"action":"input_boolean.turn_off","target":{"entity_id":["input_boolean.thermostat_hold","input_boolean.babysitter_mode"]}},{"if":[{"condition":"state","entity_id":"person.tomallison24","state":"not_home"},{"condition":"state","entity_id":"person.elena","state":"not_home"}],"then":[{"action":"input_boolean.turn_on","target":{"entity_id":"input_boolean.thermostat_eco"}}]},{"action":"script.thermostat_apply"}],"mode":"single"},"blink_enrolment_once":{"alias":"Blink — one enrolment attempt","description":"A single switch.turn_on / switch.turn_off against a list of Blink motion-detection switches. Exists to be fired-and-forgotten by blink_set_enrolment so that a Blink exception cannot kill the retry loop. Not meant to be called on its own.","sequence":[{"action":"switch.turn_{{ state }}","target":{"entity_id":"{{ entities }}"}}],"mode":"parallel"},"blink_set_enrolment":{"alias":"Blink — set enrolment, verify, retry","description":"Sets a list of Blink motion-detection switches on or off, waits 10s, reads them back, and retries whichever ones did not take - up to three attempts. If any are still wrong after that, tells Tom which rooms and which routine asked.","sequence":[{"variables":{"cams":"{{ entities | map('replace', 'switch.', '') | map('replace', '_camera_motion_detection', '') | list }}"}},{"action":"input_text.set_value","continue_on_error":true,"target":{"entity_id":"input_text.signal_blink_paused"},"data":{"value":"{{ states('input_text.signal_blink_paused').split(',') | select\n   | reject('in', cams) | join(',') }}"}},{"action":"script.turn_off","continue_on_error":true,"target":{"entity_id":"{{ entities | map('replace', 'switch.', 'script.pause_') | list }}"}},{"repeat":{"until":[{"condition":"template","value_template":"{{ repeat.index >= 3 or\n   (expand(entities) | rejectattr('state', 'eq', state) | list | count) == 0 }}"}],"sequence":[{"action":"script.turn_on","target":{"entity_id":"script.blink_enrolment_once"},"data":{"variables":{"state":"{{ state }}","entities":"{{ expand(entities) | rejectattr('state', 'eq', state)\n   | map(attribute='entity_id') | list }}"}}},{"delay":"00:00:10"}]}},{"variables":{"still_wrong":"{{ expand(entities) | rejectattr('state', 'eq', state)\n   | map(attribute='name') | list }}"}},{"condition":"template","value_template":"{{ still_wrong | count > 0 }}"},{"action":"notify.send_message","target":{"entity_id":"notify.tom_fs_iphone"},"data":{"title":"Blink didn't take the change","message":"{{ reason }} asked for motion detection {{ state | upper }} but after 3 tries these are still wrong: {{ still_wrong | join(', ') }}. Check the Blink app or re-run the routine."}}],"mode":"restart"},"signal_lr_push_setpoint":{"alias":"Signal — Living Room push setpoint","description":"Sends the TF1 thermostat card's shown setpoints (input_number.signal_lr_set / _low / _high) to the Living Room Nest, debounced so a run of stepper taps becomes one call to Google.","sequence":[{"delay":{"milliseconds":1200}},{"choose":[{"conditions":[{"condition":"state","entity_id":"climate.living_room_living_room","state":"heat_cool"}],"sequence":[{"action":"climate.set_temperature","target":{"entity_id":"climate.living_room_living_room"},"data":{"target_temp_low":"{{ states('input_number.signal_lr_set_low') | float | round(0) }}","target_temp_high":"{{ states('input_number.signal_lr_set_high') | float | round(0) }}"}}]},{"conditions":[{"condition":"state","entity_id":"climate.living_room_living_room","state":["heat","cool"]}],"sequence":[{"action":"climate.set_temperature","target":{"entity_id":"climate.living_room_living_room"},"data":{"temperature":"{{ states('input_number.signal_lr_set') | float | round(0) }}"}}]}]},{"delay":{"seconds":15}},{"variables":{"a":{"temperature":"{{ state_attr('climate.living_room_living_room', 'temperature') }}","target_temp_low":"{{ state_attr('climate.living_room_living_room', 'target_temp_low') }}","target_temp_high":"{{ state_attr('climate.living_room_living_room', 'target_temp_high') }}"}}},{"if":[{"condition":"template","value_template":"{{ a.temperature is number }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_lr_set"},"data":{"value":"{{ a.temperature | round(0) }}"}}]},{"if":[{"condition":"template","value_template":"{{ a.target_temp_low is number and a.target_temp_high is number }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_lr_set_low"},"data":{"value":"{{ a.target_temp_low | round(0) }}"}},{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_lr_set_high"},"data":{"value":"{{ a.target_temp_high | round(0) }}"}}]}],"mode":"restart"},"signal_of_push_setpoint":{"alias":"Signal — Office push setpoint","description":"Sends the Office TF1 card's shown setpoints (input_number.signal_of_set / _low / _high) to the Office Nest, debounced. Same shape as signal_lr_push_setpoint - see the notes there.","sequence":[{"delay":{"milliseconds":1200}},{"choose":[{"conditions":[{"condition":"state","entity_id":"climate.office_office","state":"heat_cool"}],"sequence":[{"action":"climate.set_temperature","target":{"entity_id":"climate.office_office"},"data":{"target_temp_low":"{{ states('input_number.signal_of_set_low') | float | round(0) }}","target_temp_high":"{{ states('input_number.signal_of_set_high') | float | round(0) }}"}}]},{"conditions":[{"condition":"state","entity_id":"climate.office_office","state":["heat","cool"]}],"sequence":[{"action":"climate.set_temperature","target":{"entity_id":"climate.office_office"},"data":{"temperature":"{{ states('input_number.signal_of_set') | float | round(0) }}"}}]}]},{"delay":{"seconds":15}},{"variables":{"a":{"temperature":"{{ state_attr('climate.office_office', 'temperature') }}","target_temp_low":"{{ state_attr('climate.office_office', 'target_temp_low') }}","target_temp_high":"{{ state_attr('climate.office_office', 'target_temp_high') }}"}}},{"if":[{"condition":"template","value_template":"{{ a.temperature is number }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_of_set"},"data":{"value":"{{ a.temperature | round(0) }}"}}]},{"if":[{"condition":"template","value_template":"{{ a.target_temp_low is number and a.target_temp_high is number }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_of_set_low"},"data":{"value":"{{ a.target_temp_low | round(0) }}"}},{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_of_set_high"},"data":{"value":"{{ a.target_temp_high | round(0) }}"}}]}],"mode":"restart"},"signal_wm_push_setpoint":{"alias":"Signal — Windmill AC push","description":"Sends the Windmill TF1 card's shown mode, setpoint and fan speed (input_text.signal_wm_mode, input_number.signal_wm_set, input_text.signal_wm_fan) to the Windmill AC, debounced, sending only what differs. The setpoint goes only in cool or auto, and the fan speed only when the unit is not off. Then it waits for the unit to confirm and copies its real values back.","sequence":[{"delay":{"milliseconds":1200}},{"variables":{"bad":["unknown","unavailable",""],"m":"{{ states('input_text.signal_wm_mode') if states('input_text.signal_wm_mode') not in bad\n   else states('climate.windmill_ac') }}","f":"{{ states('input_text.signal_wm_fan') }}","t":"{{ states('input_number.signal_wm_set') | float(0) | round(0) }}"}},{"if":[{"condition":"template","value_template":"{{ m in ['cool', 'auto', 'fan_only', 'off'] and states('climate.windmill_ac') != m }}"}],"then":[{"action":"climate.set_hvac_mode","target":{"entity_id":"climate.windmill_ac"},"data":{"hvac_mode":"{{ m }}"}}]},{"if":[{"condition":"template","value_template":"{{ m in ['cool', 'auto'] and t >= 50 and state_attr('climate.windmill_ac', 'temperature') != t }}"}],"then":[{"action":"climate.set_temperature","target":{"entity_id":"climate.windmill_ac"},"data":{"temperature":"{{ t }}"}}]},{"if":[{"condition":"template","value_template":"{{ m != 'off' and f in ['Auto', 'Low', 'Medium', 'High'] and state_attr('climate.windmill_ac', 'fan_mode') != f }}"}],"then":[{"action":"climate.set_fan_mode","target":{"entity_id":"climate.windmill_ac"},"data":{"fan_mode":"{{ f }}"}}]},{"wait_template":"{{ states('climate.windmill_ac') == m\n   and (m == 'off' or f not in ['Auto', 'Low', 'Medium', 'High'] or state_attr('climate.windmill_ac', 'fan_mode') == f) }}","timeout":{"seconds":20},"continue_on_timeout":true},{"delay":{"seconds":3}},{"variables":{"a":{"temperature":"{{ state_attr('climate.windmill_ac', 'temperature') }}","fan_mode":"{{ state_attr('climate.windmill_ac', 'fan_mode') }}"},"s":"{{ states('climate.windmill_ac') }}"}},{"if":[{"condition":"template","value_template":"{{ s not in bad }}"}],"then":[{"action":"input_text.set_value","target":{"entity_id":"input_text.signal_wm_mode"},"data":{"value":"{{ s }}"}}]},{"if":[{"condition":"template","value_template":"{{ a.fan_mode is string and a.fan_mode != '' }}"}],"then":[{"action":"input_text.set_value","target":{"entity_id":"input_text.signal_wm_fan"},"data":{"value":"{{ a.fan_mode }}"}}]},{"if":[{"condition":"template","value_template":"{{ a.temperature is number }}"}],"then":[{"action":"input_number.set_value","target":{"entity_id":"input_number.signal_wm_set"},"data":{"value":"{{ a.temperature | round(0) }}"}}]}],"mode":"restart"},"hatch_bedtime":{"alias":"Hatch Bedtime","description":"Olivia's Hatch bedtime - White Noise at 30 %, clock display off, and the night light off (default) or green at 30 % (light green).","sequence":[{"if":[{"condition":"template","value_template":"{{ (light | default('off')) == 'green' }}"}],"then":[{"action":"media_player.select_sound_mode","target":{"entity_id":"media_player.olivias_hatch_media_player"},"data":{"sound_mode":"WhiteNoise"}},{"delay":{"seconds":2}},{"action":"light.turn_on","target":{"entity_id":"light.olivias_hatch_light"},"data":{"rgb_color":[0,255,0],"brightness_pct":30}}],"else":[{"action":"light.turn_off","target":{"entity_id":"light.olivias_hatch_light"}},{"delay":{"seconds":2}},{"action":"media_player.select_sound_mode","target":{"entity_id":"media_player.olivias_hatch_media_player"},"data":{"sound_mode":"WhiteNoise"}}]},{"delay":{"seconds":2}},{"action":"media_player.volume_set","target":{"entity_id":"media_player.olivias_hatch_media_player"},"data":{"volume_level":0.3}},{"if":[{"condition":"state","entity_id":"light.olivias_hatch_clock","state":"on"}],"then":[{"action":"light.turn_off","target":{"entity_id":"light.olivias_hatch_clock"}}]}],"mode":"restart"}};
